window.DRILLS = {"L6": {"video": "drill_l6", "title": "All At Once", "tag": "EVERYTHING AT ONCE", "nar": ["Time for the last drill of the season. Everything you've practiced arrives at once.", "Press Play. Melissa will pause the video three times to ask you a question. Take the time you need, and the video will resume when you're done."], "beats": [{"t": 8.8, "u": 30.0, "kind": "stack", "text": "", "lines": [[8.8, "The plan just changed."], [11.9, "You don't have the full picture."], [14.5, "The last thing you tried didn't work."], [17.9, "Someone you trust disagrees."], [21.6, "Your plate is already full."], [25.9, "People are watching."]]}, {"t": 30.0, "u": 36.6, "kind": "notice", "text": "Before you respond to any of it: what do you notice?"}, {"t": 47.1, "u": 65.2, "kind": "reframe", "text": "Pressure rarely arrives one variable at a time. Notice which one is pulling hardest on you. That's the information this season was built to surface."}, {"t": 65.7, "u": 76.3, "kind": "notice", "text": "What do you think first? How do you feel? What do you decide?"}, {"t": 88.3, "u": 94.4, "kind": "again", "text": "While you are still responding, one more thing changes."}, {"t": 100.8, "u": 127.1, "kind": "condition", "text": "Six lessons ago you noticed your first response. Since then you have practiced a different way through, more than once."}], "holds": [{"t": 36.55, "resume": 46.6, "key": "notice", "kind": "text", "label": "NOTICE", "q": "What do you notice right now, with all of it at once?"}, {"t": 76.25, "resume": 87.9, "key": "respond", "kind": "text", "label": "RESPOND", "q": "What do you do first? What do you protect, and what do you let go of? Who do you talk to?"}, {"t": 94.35, "resume": 100.4, "key": "again", "kind": "text", "label": "GO AGAIN", "q": "One more thing just changed. What do you change, and what do you keep?"}]}};
